BEGIN;
ALTER TABLE public.rent_bookings ADD COLUMN IF NOT EXISTS delivery_free boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.rent_free_delivery_guard() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $$
BEGIN
 IF TG_OP='INSERT' THEN NEW.delivery_free := NEW.handover_mode='delivery' AND NEW.days>=3;
 ELSE NEW.delivery_free := OLD.delivery_free;
 END IF;
 IF NEW.delivery_free THEN
  NEW.total_vnd := NEW.days*NEW.daily_vnd+NEW.collection_fee_vnd;
  NEW.delivery_fee_vnd := 0;
  IF NEW.return_mode='self' THEN NEW.logistics_quoted:=true;NEW.logistics_accepted:=true;END IF;
 END IF;
 RETURN NEW;
END$$;
REVOKE ALL ON FUNCTION public.rent_free_delivery_guard() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER rent_free_delivery BEFORE INSERT OR UPDATE ON public.rent_bookings FOR EACH ROW EXECUTE FUNCTION public.rent_free_delivery_guard();
CREATE OR REPLACE FUNCTION public.rent_terms() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT $json${"ru": "1. Бронирование. Выберите байк и даты, укажите имя и телефон. Заявка удерживает байк на 30 минут. Бронь действует после подтверждения сотрудником. До подтверждения платить не нужно.\n\n2. Цена и срок. Все суммы — во вьетнамских донгах (VND). Тариф за сутки, число суток, стоимость аренды и возвратный залог указаны в бронировании отдельно. Одни сутки — 24 часа; неполные сутки выбранного срока округляются вверх. Например, 25 часов — 2 суток. При выдаче оплаченные сутки отсчитываются от фактической передачи байка; точное время возврата отображается в аренде.\n\n3. Оплата и залог. Аренду оплачивайте после подтверждения: по QR или наличными при получении. Залог вносится отдельно до выдачи, в VND. Залог не входит в стоимость аренды. Сотрудник подтверждает фактическое получение денег; скриншот перевода сам по себе не подтверждает оплату.\n\n4. Получение. Место получения и возврата указано в бронировании. Водителю должно быть не меньше 18 лет. До выдачи сотрудник проверяет личность, действующие права подходящей категории для Вьетнама, регистрацию и страховые документы байка. Вместе осмотрите байк, комплектацию, фотографии и круговое видео. Подтвердите акт выдачи только после проверки. Ранее отмеченные повреждения вам не начисляются.\n\n5. Использование. Носите шлем. Не управляйте в состоянии опьянения и не передавайте байк другому водителю без согласования с UMMA. При неисправности или ДТП остановитесь в безопасном месте и свяжитесь с UMMA. Ремонт сначала согласуйте с сотрудником.\n\n6. Возврат и бензин. Байк выдаётся с полным баком. Верните его с полным баком, ключами и переданной комплектацией. Сотрудник оформит акт возврата с фото и видео; проверьте его и подтвердите. При неполном баке из залога вычитается только фактическая дозаправка по чеку. Чек и точную сумму вы увидите до подтверждения расчёта.\n\n7. Возврат залога. Если удержаний нет, возвращается весь залог. При дозаправке: возврат = внесённый залог минус стоимость по чеку, всё в VND. После осмотра и вашего подтверждения расчёта сотрудник возвращает деньги и фиксирует возврат в приложении. Автоматических списаний за повреждения и опоздание нет. Спорные требования обсуждаются отдельно; не подтверждайте расчёт, с которым не согласны.\n\n8. Продление и отмена. Продление согласуйте заранее: оно возможно, если байк свободен. Доплата рассчитывается по суточному тарифу вашего бронирования. При опоздании сразу свяжитесь с UMMA. До выдачи неоплаченную бронь можно отменить в приложении; для оплаченной обратитесь к сотруднику — полученная аренда и залог возвращаются полностью.\n\n9. Доставка и выезд за байком. Самостоятельное получение и возврат в месте бронирования бесплатны. Доставка к вам и выезд за байком — две отдельные услуги. Укажите точки на карте и ориентиры. При аренде от 3 суток доставка байка к клиенту бесплатна (0 ₫). При аренде на 1–2 суток стоимость доставки согласует менеджер. Выезд за байком при возврате оплачивается отдельно по согласованию.  До вашего подтверждения суммы оплата и выдача недоступны. Стоимость услуг указана отдельно от аренды и залога. При отмене до выдачи возвращается вся полученная оплата по правилу пункта 8. При выезде за байком аренда заканчивается после фактической передачи сотруднику и оформления возврата; отправка заявки сама по себе её не завершает. Если место или время передачи нужно изменить, заранее свяжитесь с UMMA.", "en": "1. Booking. Choose a bike and dates, then enter your name and phone. Your request holds the bike for 30 minutes. The booking is valid after staff confirmation. Do not pay before confirmation.\n\n2. Price and duration. All amounts are in Vietnamese dong (VND). Your booking separately shows the daily rate, days, rental total and refundable deposit. One day is 24 hours; a partial day in the selected period rounds up. For example, 25 hours means 2 days. Paid days begin at actual handover; the exact return time appears in your rental.\n\n3. Payment and deposit. After confirmation, pay rent by QR or cash at pickup. Pay the separate deposit in VND before handover. The deposit is not part of the rental price. Staff confirms actual receipt of funds; a transfer screenshot alone does not confirm payment.\n\n4. Pickup. Your booking shows the pickup and return location. The agreed rider must be 18 or older. Staff checks identity, a valid licence of the appropriate category for Vietnam, vehicle registration and insurance documents. Inspect the bike, accessories, photos and walk-around video together. Accept the pickup report only after checking. Previously recorded damage is not charged to you.\n\n5. Use. Wear a helmet. Do not ride intoxicated or give the bike to another rider without UMMA approval. In a breakdown or accident, stop safely and contact UMMA. Agree repairs with staff first.\n\n6. Return and fuel. The bike is handed over with a full tank. Return it full, with keys and all supplied accessories. Staff records the return with photos and video; review and accept the report. If fuel is missing, only actual refuelling cost supported by a receipt is deducted from the deposit. Review the receipt and exact amount before accepting settlement.\n\n7. Deposit refund. Without deductions, the full deposit is refunded. For refuelling: refund = deposit paid minus receipted fuel cost, all in VND. After inspection and your acceptance of settlement, staff refunds the money and records it in the app. No automatic damage or late charges apply. Discuss disputed claims separately; do not accept a settlement you disagree with.\n\n8. Extensions and cancellation. Arrange an extension in advance; it requires availability. Extra rent uses the daily rate in your booking. Contact UMMA immediately if late. Before handover, cancel an unpaid booking in the app. For a paid booking, contact staff for a full refund of received rent and deposit.\n\n9. Delivery and collection. Self pickup and return at the booking location are free. Delivery to you and collection from you are separate optional services. Select map points and provide landmarks. Delivery to the customer is free (0 ₫) for rentals of 3 days or more. For 1–2 days, staff agrees the delivery fee. Return collection is priced separately by agreement.  Payment and handover are unavailable until you accept the amount. Service fees are shown separately from rent and deposit. Cancellation before handover refunds all received payment under clause 8. With collection, the rental ends after actual handover to staff and the return report, not when you send a request. Contact UMMA in advance to change the location or time.", "vi": "1. Đặt xe. Chọn xe và thời gian, nhập họ tên và số điện thoại. Yêu cầu giữ xe trong 30 phút. Đơn có hiệu lực sau khi nhân viên xác nhận. Chưa cần thanh toán trước khi xác nhận.\n\n2. Giá và thời hạn. Mọi khoản tiền đều bằng đồng Việt Nam (VND). Đơn hiển thị riêng giá mỗi ngày, số ngày, tổng tiền thuê và tiền cọc được hoàn. Một ngày là 24 giờ; thời gian lẻ trong khoảng đã chọn được làm tròn lên. Ví dụ: 25 giờ tính 2 ngày. Thời gian đã trả tiền bắt đầu từ lúc bàn giao thực tế; giờ trả chính xác hiển thị trong đơn thuê.\n\n3. Thanh toán và cọc. Sau khi xác nhận, trả tiền thuê bằng QR hoặc tiền mặt khi nhận xe. Nộp cọc riêng bằng VND trước khi giao xe. Cọc không nằm trong giá thuê. Nhân viên xác nhận tiền thực nhận; ảnh chuyển khoản không tự xác nhận thanh toán.\n\n4. Nhận xe. Địa điểm nhận và trả hiển thị trong đơn. Người lái đã thỏa thuận phải đủ 18 tuổi. Nhân viên kiểm tra danh tính, giấy phép đúng hạng có hiệu lực tại Việt Nam, đăng ký và bảo hiểm xe. Cùng kiểm tra xe, phụ kiện, ảnh và video quanh xe. Chỉ xác nhận biên bản giao sau khi kiểm tra. Không tính phí cho hư hỏng đã ghi nhận trước đó.\n\n5. Sử dụng. Đội mũ bảo hiểm. Không lái khi say hoặc giao xe cho người khác khi chưa được UMMA đồng ý. Khi xe hỏng hoặc tai nạn, dừng an toàn và liên hệ UMMA. Thống nhất với nhân viên trước khi sửa chữa.\n\n6. Trả xe và xăng. Nhận xe đầy bình. Trả xe đầy bình, đủ chìa khóa và phụ kiện đã nhận. Nhân viên lập biên bản trả với ảnh và video; hãy kiểm tra rồi xác nhận. Nếu thiếu xăng, chỉ trừ tiền đổ thêm thực tế theo hóa đơn. Bạn được xem hóa đơn và số tiền chính xác trước khi đồng ý quyết toán.\n\n7. Hoàn cọc. Không có khấu trừ thì hoàn đủ cọc. Khi đổ thêm xăng: tiền hoàn = cọc đã nộp trừ tiền xăng theo hóa đơn, đều bằng VND. Sau kiểm tra và khi bạn đồng ý quyết toán, nhân viên hoàn tiền và ghi nhận trong ứng dụng. Không tự động trừ tiền do hư hỏng hoặc trả muộn. Yêu cầu còn tranh chấp được trao đổi riêng; không xác nhận quyết toán nếu chưa đồng ý.\n\n8. Gia hạn và hủy. Liên hệ trước để gia hạn; chỉ gia hạn khi xe còn trống. Tiền thêm tính theo giá mỗi ngày trong đơn. Nếu trả muộn, liên hệ UMMA ngay. Trước khi giao xe, có thể hủy đơn chưa thanh toán trong ứng dụng. Đơn đã thanh toán cần liên hệ nhân viên để hoàn toàn bộ tiền thuê và cọc đã nhận.\n\n9. Giao và nhận lại xe. Tự nhận và trả tại địa điểm trong đơn là miễn phí. Giao xe đến bạn và đến nhận lại xe là hai dịch vụ riêng. Chọn điểm trên bản đồ và ghi địa chỉ, mốc nhận biết. Miễn phí giao xe đến khách (0 ₫) khi thuê từ 3 ngày. Thuê 1–2 ngày, nhân viên thỏa thuận phí giao. Phí đến nhận lại xe được thỏa thuận riêng.  Chưa thanh toán và giao xe khi bạn chưa đồng ý số tiền. Phí dịch vụ hiển thị riêng tiền thuê và cọc. Hủy trước khi giao xe được hoàn toàn bộ tiền đã nhận theo mục 8. Khi đến nhận lại xe, đơn thuê chỉ kết thúc sau khi thực bàn giao cho nhân viên và lập biên bản trả, không phải lúc gửi yêu cầu. Liên hệ UMMA trước nếu cần đổi nơi hoặc giờ bàn giao."}$json$::jsonb $$;
COMMIT;
